WITH not_flagged AS (SELECT s.* FROM products s WHERE NOT EXISTS (SELECT 1 FROM inventory x WHERE x.product_id = s.id AND x.store_id IN (1, 3, 4, 6))) SELECT id, product_name, category, brand, price, cost, launch_date, tags, supplier_id, CASE WHEN category RLIKE '^(Home|Fashion)$' THEN 'GROUP_B' WHEN category RLIKE '^(Electronics|Sports)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS category_zone FROM not_flagged ORDER BY brand;
